package com.bank.k8s.model;

// Ephemeral unit. Gets a fresh IP each time it is created; no durable identity.
public class Pod {
    private final String name;
    private final String ip;
    private boolean alive = true;

    public Pod(String name, String ip) {
        this.name = name;
        this.ip = ip;
    }

    public void kill() { this.alive = false; } // node failure / eviction
    public boolean isAlive() { return alive; }
    public String getName() { return name; }
    public String getIp() { return ip; }
}
