package com.bank.k8s.controller;

import com.bank.k8s.model.Pod;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.logging.Logger;

// Keeps 'desired' live Pods. Recreates any that die — this is self-healing.
public class Deployment {
    private static final Logger log = Logger.getLogger(Deployment.class.getName());
    private final int desired;
    private final List<Pod> pods = new ArrayList<>();

    public Deployment(int desired) {
        this.desired = desired;
        reconcile(); // bring actual state up to desired
    }

    // The core Kubernetes idea: compare actual to desired, fix the difference.
    public void reconcile() {
        pods.removeIf(p -> !p.isAlive()); // drop dead cattle
        while (pods.size() < desired) {
            String ip = "10.0.0." + (10 + pods.size());
            Pod fresh = new Pod("transfer-" + UUID.randomUUID().toString().substring(0, 5), ip);
            pods.add(fresh);
            log.info(() -> "created pod " + fresh.getName() + " @ " + fresh.getIp());
        }
    }

    public List<Pod> livePods() {
        return pods.stream().filter(Pod::isAlive).toList();
    }

    public void killOne() {
        if (!pods.isEmpty()) {
            Pod victim = pods.get(0);
            victim.kill();
            log.warning(() -> "pod " + victim.getName() + " died (node failure)");
        }
    }
}
