package com.bank.k8s.network;

import com.bank.k8s.controller.Deployment;
import com.bank.k8s.model.Pod;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Stable front for unstable Pods. Round-robins across whatever is live now.
public class Service {
    private static final Logger log = Logger.getLogger(Service.class.getName());
    private final Deployment deployment;
    private final AtomicInteger counter = new AtomicInteger(0);

    public Service(Deployment deployment) { this.deployment = deployment; }

    // Route a request to one of the currently live Pods.
    public String route() {
        List<Pod> live = deployment.livePods();
        if (live.isEmpty()) return "NO HEALTHY POD";
        Pod chosen = live.get(counter.getAndIncrement() % live.size());
        log.info(() -> "service routed request -> " + chosen.getName() + " @ " + chosen.getIp());
        return chosen.getIp();
    }
}
