package com.bank.k8s.config;

import java.util.Map;
import java.util.logging.Logger;

// Models a merged ConfigMap (non-secret) and Secret (sensitive) view.
public class ConfigStore {
    private static final Logger log = Logger.getLogger(ConfigStore.class.getName());
    private final Map<String, String> configMap;
    private final Map<String, String> secret;

    public ConfigStore(Map<String, String> configMap, Map<String, String> secret) {
        this.configMap = configMap;
        this.secret = secret;
    }

    public String config(String key) {
        String v = configMap.get(key);
        log.info(() -> "config " + key + " = " + v);
        return v;
    }

    public String secret(String key) {
        // Reference secrets by key name; never log the actual value.
        log.info(() -> "secret " + key + " = ****** (resolved, not logged)");
        return secret.get(key);
    }
}
