package com.bank.k8s;

import com.bank.k8s.config.ConfigStore;
import com.bank.k8s.controller.Deployment;
import com.bank.k8s.network.Service;
import java.util.Map;

public class K8sDemo {
    public static void main(String[] args) {
        // Deployment keeps 3 Pods alive.
        Deployment deployment = new Deployment(3);
        Service service = new Service(deployment);

        // Route a few requests across the live Pods.
        service.route();
        service.route();
        service.route();

        // A node fails: one Pod dies. The Deployment self-heals.
        deployment.killOne();
        deployment.reconcile();       // replaces the dead Pod with a new one
        service.route();              // service transparently uses the new Pod

        // Read config (ConfigMap) and a secret (Secret).
        ConfigStore store = new ConfigStore(
            Map.of("LOG_LEVEL", "INFO", "FRAUD_SERVICE_URL", "http://fraud-service"),
            Map.of("DB_PASSWORD", "s3cr3tPass"));
        store.config("LOG_LEVEL");
        store.secret("DB_PASSWORD");
    }
}
